void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
#if USE_TEXTURE
  in vec2 uv0;
  uniform sampler2D cc_spriteTexture;
#endif
float drawBambooLeaf(vec2 uv, vec2 center, float angle, vec2 size) {
  vec2 d = uv - center;
  d.x *= 1.7778;
  float c = cos(angle);
  float s = sin(angle);
  vec2 r = vec2(d.x * c - d.y * s, d.x * s + d.y * c);
  r.y -= (r.x * r.x) * 3.2;
  float dist = (r.x * r.x) / (size.x * size.x) + (r.y * r.y) / (size.y * size.y);
  return smoothstep(1.0, 0.45, dist);
}
vec4 frag () {
  vec4 o = vec4(1.0, 1.0, 1.0, 1.0);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
    #if IS_GRAY
      float gray  = 0.2126 * o.r + 0.7152 * o.g + 0.0722 * o.b;
      o.r = o.g = o.b = gray;
    #endif
  #endif
  float t = cc_time.x;
  float cloudTime = t * 0.025;
  vec2 cuv1 = vec2(uv0.x * 2.2 - cloudTime, uv0.y * 3.2);
  vec2 cuv2 = vec2(uv0.x * 3.8 - cloudTime * 1.6 + 0.4, uv0.y * 5.0 + 0.3);
  float c1 = sin(cuv1.x) * cos(cuv1.y) + sin(cuv1.x * 1.7 + cuv1.y * 0.8);
  float c2 = sin(cuv2.x) * cos(cuv2.y * 0.8) + cos(cuv2.x * 0.6 - cuv2.y * 1.1);
  float cloudDensity = smoothstep(0.45, 1.25, (c1 + c2 * 0.5));
  float skyMask = smoothstep(0.35, 0.75, uv0.y);
  float cloudAlpha = cloudDensity * skyMask * 0.22;
  vec3 cloudCol = vec3(1.0, 1.0, 0.96);
  o.rgb = mix(o.rgb, cloudCol, cloudAlpha);
  float totalLeafMask = 0.0;
  vec3 leafColor = vec3(0.35, 0.76, 0.24);
  vec3 leafHighlight = vec3(0.58, 0.88, 0.32);
  float x1 = fract(t * 0.075 + 0.12) * 1.3 - 0.15;
  float y1 = 0.72 + sin(t * 1.7 + 1.2) * 0.045;
  float m1 = drawBambooLeaf(uv0, vec2(x1, y1), sin(t * 2.3 + 1.2) * 0.45 + 0.2, vec2(0.028, 0.008));
  float x2 = fract(t * 0.092 + 0.48) * 1.3 - 0.15;
  float y2 = 0.58 + sin(t * 1.9 + 2.8) * 0.05;
  float m2 = drawBambooLeaf(uv0, vec2(x2, y2), sin(t * 2.6 + 2.8) * 0.5 + 0.15, vec2(0.032, 0.009));
  float x3 = fract(t * 0.068 + 0.82) * 1.3 - 0.15;
  float y3 = 0.83 + sin(t * 1.5 + 4.1) * 0.04;
  float m3 = drawBambooLeaf(uv0, vec2(x3, y3), sin(t * 2.1 + 4.1) * 0.4 + 0.25, vec2(0.026, 0.0075));
  float x4 = fract(t * 0.088 + 0.31) * 1.3 - 0.15;
  float y4 = 0.42 + sin(t * 1.8 + 0.5) * 0.048;
  float m4 = drawBambooLeaf(uv0, vec2(x4, y4), sin(t * 2.4 + 0.5) * 0.48 + 0.1, vec2(0.030, 0.0085));
  float x5 = fract(t * 0.082 + 0.65) * 1.3 - 0.15;
  float y5 = 0.28 + sin(t * 2.0 + 3.4) * 0.042;
  float m5 = drawBambooLeaf(uv0, vec2(x5, y5), sin(t * 2.7 + 3.4) * 0.52 + 0.2, vec2(0.027, 0.008));
  float x6 = fract(t * 0.062 + 0.95) * 1.3 - 0.15;
  float y6 = 0.64 + sin(t * 1.4 + 5.2) * 0.035;
  float m6 = drawBambooLeaf(uv0, vec2(x6, y6), sin(t * 1.9 + 5.2) * 0.38 + 0.18, vec2(0.022, 0.006));
  totalLeafMask = clamp(m1 + m2 + m3 + m4 + m5 + m6, 0.0, 1.0);
  vec3 finalLeafCol = mix(leafColor, leafHighlight, clamp(sin(t * 3.0) * 0.5 + 0.5, 0.2, 0.8));
  o.rgb = mix(o.rgb, finalLeafCol, totalLeafMask * 0.92);
  o *= color;
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

